type Address = { line1: string; city: string; country: string; postcode?: string };

type MyPartial<T> = { [K in keyof T]?: T[K] };
type MyRequired<T> = { [K in keyof T]-?: T[K] };
type MyPick<T, K extends keyof T> = { [P in K]: T[P] };
type MyOmit<T, K extends PropertyKey> = { [P in keyof T as Exclude<P, K>]: T[P] };

type FieldState<T> = {
  [K in keyof T]: { value: T[K]; error: string | null; touched: boolean };
};

type Setters<T> = {
  [K in keyof T as `set${Capitalize<K & string>}`]: (value: T[K]) => void;
};

function initialState<T extends object>(values: T): FieldState<T> {
  // Object.fromEntries cannot know the keys, so we cast once here.
  return Object.fromEntries(
    Object.entries(values).map(([key, value]) => [key, { value, error: null, touched: false }]),
  ) as FieldState<T>;
}

// ---- Type tests (do not edit) ----
type T1 = Expect<Equal<MyPartial<Address>, { line1?: string; city?: string; country?: string; postcode?: string }>>;
type T2 = Expect<Equal<MyRequired<Address>, { line1: string; city: string; country: string; postcode: string }>>;
type T3 = Expect<Equal<MyPick<Address, 'city' | 'postcode'>, { city: string; postcode?: string }>>;
type T4 = Expect<Equal<MyOmit<Address, 'postcode' | 'country'>, { line1: string; city: string }>>;
type T5 = Expect<Equal<FieldState<{ city: string; floor: number }>, {
  city: { value: string; error: string | null; touched: boolean };
  floor: { value: number; error: string | null; touched: boolean };
}>>;
type T6 = Expect<Equal<Setters<{ city: string; floor: number }>, {
  setCity: (value: string) => void;
  setFloor: (value: number) => void;
}>>;

const form = initialState({ line1: '12 Nile St', city: 'Cairo', country: 'EG' });
console.log(form.city);
